        var y = Math.max(-rect.y, 0);
        sprite.setFrame(0, y, rect.width, rect.height - y);
        sprite.opacity = 255 - sprite.logScrollXDuration * 20;
        if (sprite.viewDuration > 0)
            sprite.viewDuration--;
    }
    if (this._clearDuration > 0) {
        this._clearDuration--;
