`a:link {
				color: #33ccff;
			}

			table {
				border-collapse: collapse;
				width: 100%;
			}

			option {
				text-align: center;
			}

			th, td {
				padding: 16px;
				border-bottom: 1px solid ${tableBorder};
				background-color: ${trueBackgroundColor};
			}

			td {
				text-align: left;
			}

			th {
				text-align: center;
			}

			button {
				display: inline-block;
				padding: 5px 10px;
				font-size: 15px;
				cursor: pointer;
				text-align: center;
				text-decoration: none;
				outline: none;
				color: #fff;
				background-color: ${buttonColor};
				border: none;
				border-radius: 15px;
				box-shadow: 0 4px ${buttonShadow};
			}

			button:hover {background-color: ${buttonColor2}}

			button:active {
				background-color: ${buttonColor2};
				box-shadow: 0 2px ${pushedButtonShadow};
				transform: translateY(2px);
			}

			ul {
				list-style-type: none;
				margin: 0;
				padding: 0;
				overflow: hidden;
				border: 1px solid ${borderColor};
				background-color: ${backgroundColor};
			}

			li {
				float: left;
				background-color: ${topMenuNoSelect}
			}

			li a {
				display: block;
				color: ${topMenuText};
				text-align: center;
				padding: 14px 16px;
				text-decoration: none;
			}

			li a:hover:not(.active) {
				background-color: ${topMenuHighlight};
			}

			li a.active {
				color: white;
				background-color: ${baseColor};
			}

			#LaunchButton {
				display: inline-block;
				border-radius: 4px;
				border: none;
				color: #FFFFFF;
				font-size: 18px;
				padding: 14px;
				width: 200px;
				height: 50px;
				transition: all 0.5s;
				cursor: pointer;
				margin: 5px;
				vertical-align:middle; 
				text-align: center;
			}

			#LaunchButton span {
				cursor: pointer;
				display: inline-block;
				position: relative;
				transition: 0.5s;
			}

			#LaunchButton span:after {
				content: '\\21D2';
				position: absolute;
				opacity: 0;
				top: -4px;
				right: -30px;
				transition: 0.5s;
			}

			#LaunchButton:hover span {
				padding-right: 35px;
			}

			#LaunchButton:hover span:after {
				opacity: 1;
				right: 0;
			}

			.dropbtn {
				display: inline-block;
				color: white;
				text-align: center;
				padding: 14px 16px;
				text-decoration: none;
			}

			li.dropdown {
				display: inline-block;
			}

			.dropdown-content {
				display: none;
				position: absolute;
				background-color: ${topMenuNoSelect};
				min-width: 160px;
				box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);
				z-index: 1;
			}

			.dropdown-content a {
				color: ${topMenuText};
				background-color: ${topMenuNoSelect};
				padding: 12px 16px;
				text-decoration: none;
				display: block;
				text-align: left;
			}

			.dropdown-content a:hover {
				background-color: ${topMenuHighlight};
			}

			.dropdown:hover .dropdown-content {
				display: block;
			}

			textarea, select {
				background-color: ${inputBackground};
				border-color: ${inputBorder};
				color: ${textColor};
				padding: 3px 0px 3px 3px;
				margin: 5px 1px 3px 0px;
			}

			input {
				border: 1px solid ${inputBorder};
				background-color: ${inputBackground};
				color: ${textColor};
				padding: 1px 3px 1px 3px;
			}

			input[type=text]:focus, textarea:focus, select:focus {
				box-shadow: 0 0 5px ${inputHighlight};
				border: 1px solid ${inputHighlight};
			}

			#scrollStuff::-webkit-scrollbar {
				width: 1em;
			}

			#scrollStuff::-webkit-scrollbar-track {
				background-color: ${scrollBack};
			}

			#scrollStuff::-webkit-scrollbar-thumb {
				background-color: ${trueBackgroundColor};
				outline: 1px solid slategrey;
				outline-offset: -1px;
			}

			#scrollStuff::-webkit-scrollbar-corner {
				background-color: ${scrollBack};
			}`

